window.LOGO_C={"claude":"#D97757","anthropic":"#F0EEE6","googlegemini":"#8E75B2","google":"#4285F4","replit":"#F26207","stackblitz":"#1389FD","huggingface":"#FFD21E","deepseek":"#4D6BFE","alibabacloud":"#FF6A00","qwen":"#7C6CF0","xiaomi":"#FF6900","meta":"#0467DF","mistralai":"#FA520F","nvidia":"#76B900","cloudflare":"#F38020","figma":"#F24E1E","linear":"#8A93F0","docker":"#2496ED","slack":"#E01E5A","googlechrome":"#4285F4","perplexity":"#1FB8CD","sentry":"#A78BFA","visualstudiocode":"#3EA6FF","amazonaws":"#FF9900","codeium":"#09B6A2","netlify":"#00C7B7","shopify":"#95BF47","linuxfoundation":"#5DADE2","jetbrains":"#ffffff","claudecode":"#D97757","trae":"#32F08C","codebuddy":"#9B87FF","googlejules":"#A78BFA","xcode":"#4AA8FF","androidstudio":"#5CD68C","v0":"#E8ECF3","ollama":"#E8ECF3","openrouter":"#C7CBE0","coze":"#4D53E8","devin":"#F0B429","lovable":"#F472B6","kiro":"#A78BFA","qoder":"#6FA8FF","antigravity":"#7AA7FF","kilocode":"#C4B5FD","codex":"#E8ECF3","geminicli":"#9D8BD1","amp":"#FB923C","mcp":"#E8ECF3","lobehub":"#E8ECF3","ico-bench":"#38BDF8","ico-agent":"#A78BFA","ico-alert":"#F87171","ico-shield":"#F472B6","ico-ctx":"#7DD3FC","ico-pack":"#A78BFA","ico-team":"#E0B354"};
window.BRANDS={"Claude Code":["claudecode","#D97757"],"GitHub Copilot":["githubcopilot","#E8ECF3"],"Copilot Workspace":["githubcopilot","#E8ECF3"],"Copilot":["githubcopilot","#E8ECF3"],"CodeBuddy Code":["codebuddy","#9B87FF"],"CodeBuddy":["codebuddy","#9B87FF"],"Gemini CLI":["geminicli","#9D8BD1"],"Gemini":["googlegemini","#8E75B2"],"Codex CLI":["codex","#E8ECF3"],"Codex":["codex","#E8ECF3"],"Qwen Code":["qwen","#7C6CF0"],"Qwen":["qwen","#7C6CF0"],"Cursor":["cursor","#E8ECF3"],"Windsurf":["windsurf","#7EE0C4"],"Trae":["trae","#32F08C"],"Qoder":["qoder","#6FA8FF"],"Antigravity":["antigravity","#7AA7FF"],"Kiro":["kiro","#A78BFA"],"TRAE":["trae","#32F08C"],"Devin":["devin","#F0B429"],"Cognition":["devin","#F0B429"],"Lovable":["lovable","#F472B6"],"Bolt":["stackblitz","#1389FD"],"StackBlitz":["stackblitz","#1389FD"],"Replit":["replit","#F26207"],"v0":["v0","#E8ECF3"],"Vercel":["vercel","#E8ECF3"],"Kilo Code":["kilocode","#C4B5FD"],"Cline":["cline","#7DD3FC"],"OpenCode":["opencode","#86EFAC"],"Amp":["amp","#FB923C"],"Aider":["","#86EFAC","A"],"Continue":["","#38BDF8","C"],"Crush":["","#F472B6","C"],"Augment":["","#FBBF24","A"],"Sourcegraph":["","#F472B6","S"],"Droid":["","#A78BFA","D"],"Factory":["","#A78BFA","F"],"Jules":["googlejules","#A78BFA"],"Supermaven":["","#94A3B8","S"],"DeepSeek":["deepseek","#4D6BFE"],"Claude":["claude","#D97757"],"Anthropic":["anthropic","#F0EEE6"],"OpenAI":["openai","#E8ECF3"],"ChatGPT":["openai","#E8ECF3"],"GPT-4":["openai","#E8ECF3"],"GPT-5":["openai","#E8ECF3"],"Google":["google","#4285F4"],"MCP":["mcp","#E8ECF3"],"Model Context Protocol":["mcp","#E8ECF3"],"ACP":["zedindustries","#22D3EE"],"Zed":["zedindustries","#6FA8FF"],"AGENTS.md":["openai","#FBBF24"],"Skills":["anthropic","#FB923C"],"Agent Skills":["anthropic","#FB923C"],"JetBrains":["jetbrains","#E8ECF3"],"Xcode":["xcode","#4AA8FF"],"Android Studio":["androidstudio","#5CD68C"],"Apple":["apple","#E8ECF3"],"GitHub":["github","#E8ECF3"],"VS Code":["visualstudiocode","#3EA6FF"],"Figma":["figma","#F24E1E"],"Linear":["linear","#8A93F0"],"Slack":["slack","#E01E5A"],"Docker":["docker","#2496ED"],"Cloudflare":["cloudflare","#F38020"],"Hugging Face":["huggingface","#FFD21E"],"NVIDIA":["nvidia","#76B900"],"Mistral":["mistralai","#FA520F"],"Perplexity":["perplexity","#1FB8CD"],"SpaceX":["spacex","#E8ECF3"],"xAI":["x","#E8ECF3"],"Grok":["x","#E8ECF3"],"Kimi":["kimi","#7DD3FC"],"阿里":["alibabacloud","#FF6A00"],"字节":["","#38BDF8","字"],"腾讯":["","#60A5FA","腾"],"MicroVM":["docker","#22D3EE"],"Agents API":["openai","#E8ECF3"],"Agent SDK":["cursor","#E8ECF3"],"扣子编程":["coze","#4D53E8"],"Coze 2.0":["coze","#4D53E8"],"Coze":["coze","#4D53E8"],"LobeHub CAO":["lobehub","#E8ECF3"],"LobeHub":["lobehub","#E8ECF3"],"DSH":["deepseek","#4D6BFE"]};
(function(){
 var ready=false;
 function ensure(){
  if(ready)return;
  if(document.getElementById('logoSprite')){ready=true;return}
  var h='<svg id="logoSprite" aria-hidden="true" style="position:absolute;width:0;height:0;overflow:hidden;pointer-events:none">';
  for(var k in LOGOS){var v=LOGOS[k];h+='<symbol id="i-'+k+'" viewBox="0 0 24 24">'+(v.charAt(0)==='<'?v:'<path d="'+v+'"/>')+'</symbol>'}
  (document.body||document.documentElement).insertAdjacentHTML('beforeend',h+'</svg>');
  ready=true;
 }
 function inner(n){var v=LOGOS[n];return v?(v.charAt(0)==='<'?v:'<path d="'+v+'"/>'):''}
 function col(n,el){return (el&&el.dataset.c)||LOGO_C[n]||'#fff'}
 function fill(root){
  var a=root.querySelectorAll('[data-l]');
  if(a.length){ensure();for(var i=0;i<a.length;i++){var el=a[i],n=el.dataset.l;
   if(!LOGOS[n]||el.dataset.done)continue;
   el.innerHTML='<svg viewBox="0 0 24 24" fill="'+col(n,el)+'" aria-hidden="true"><use href="#i-'+n+'"/></svg>';
   el.dataset.done='1'}}
  var b=root.querySelectorAll('[data-svgl]');
  for(var j=0;j<b.length;j++){var e=b[j],nn=e.dataset.svgl;
   if(!LOGOS[nn]||e.dataset.done)continue;
   e.innerHTML='<g fill="'+col(nn,e)+'">'+inner(nn)+'</g>';e.dataset.done='1'}
  /* real profile photos from the inlined AVATARS table */
  var av=root.querySelectorAll('[data-av]');
  for(var k=0;k<av.length;k++){var v=av[k],key=v.dataset.av;
   if(v.dataset.done||!window.AVATARS||!AVATARS[key])continue;
   v.innerHTML='<img src="'+AVATARS[key]+'" alt="" decoding="async">';
   v.classList.add('avimg');v.dataset.done='1'}
 }
 var ALIAS=Object.keys(BRANDS).sort(function(x,y){return y.length-x.length});
 function badge(name,size){
  var v=BRANDS[name],c=v[1];
  return v[0]?'<span class="lg '+size+'" data-l="'+v[0]+'" data-c="'+c+'"></span>'
             :'<span class="lg '+size+' m" style="--mc:'+c+'">'+v[2]+'</span>';
 }
 /* longest alias wins; short latin names need a word boundary */
 window.brandOf=function(txt){
  var low=(txt||'').toLowerCase();if(!low)return null;
  for(var j=0;j<ALIAS.length;j++){
   var a=ALIAS[j],idx=low.indexOf(a.toLowerCase());
   if(idx<0)continue;
   if(/^[\x20-\x7e]+$/.test(a)&&a.length<5){
    var before=idx>0?low[idx-1]:'',after=low[idx+a.length]||'';
    if(/[a-z0-9]/.test(before)||/[a-z0-9]/.test(after))continue;
   }
   return a;
  }
  return null;
 };
 window.brandBadge=function(name,size){return name?badge(name,size||'tiny'):''};
 /* every row in the tool landscape gets a mark; unknown names fall back to a coloured initial */
 var FIX={'Amp · Crush':'Amp','Cline · Kilo Code':'Cline','Xcode · Android Studio':'Xcode','OpenCode · Aider':'OpenCode'};
 function toolBadge(name,c){
  var k=FIX[name]||window.brandOf(name);
  if(k)return badge(k,'mini');
  var ch=((name||'').match(/[A-Za-z0-9]/)||[])[0]||(name||'·').charAt(0);
  return '<span class="lg mini m" style="--mc:'+(c||'#94a3b8')+'">'+ch+'</span>';
 }
 var toolsDone=false;
 window.decorateTools=function(){
  if(toolsDone)return;toolsDone=true;
  /* paged deck: replace the colour dot with a real mark */
  var a=document.querySelectorAll('.tmitem');
  for(var i=0;i<a.length;i++){
   var it=a[i],b=it.querySelector('b'),u=it.querySelector('u');
   if(!b||!u)continue;
   var mm=(u.getAttribute('style')||'').match(/--mc:\s*([^;]+)/);
   u.outerHTML=toolBadge(b.textContent,mm?mm[1]:'#94a3b8');
  }
  /* scroll story: inject a mark into each tool row */
  var z=document.querySelectorAll('.tmc .it');
  for(var j=0;j<z.length;j++){
   var el=z[j],bb=el.querySelector('b');
   if(!bb||el.querySelector('.lg'))continue;
   var c=getComputedStyle(el.closest('.tmc')).getPropertyValue('--mc').trim();
   el.insertAdjacentHTML('afterbegin',toolBadge(bb.textContent,c||'#94a3b8'));
  }
 };
 var SEL='.card .h,.blk>h2,.blk>h3,.dir,.row,.bw,.flow,.tweet .who,.bh,.colt';
 window.brandify=function(root){
  root=root||document;
  var list=root.querySelectorAll(SEL);
  for(var i=0;i<list.length;i++){
   var el=list[i];
   if(el.dataset.br||el.querySelector('.lg'))continue;
   el.dataset.br='1';
   var full=el.textContent||'';if(!full||full.length>90)continue;
   /* card headers carry a date in <em>; matching against the whole string makes
      short names like "v0" fail the word-boundary check ("v02023.10") */
   var main=(el.querySelector('b')||{}).textContent||'';
   var hit=window.brandOf(main)||window.brandOf(full);if(!hit)continue;
   var isHead=/^H[23]$/.test(el.tagName);
   el.insertAdjacentHTML('afterbegin',badge(hit,isHead?'hd':'tiny')+(isHead?'&nbsp;':''));
  }
  /* upgrade old letter-monogram badges to real marks where a source is now available */
  var mono=root.querySelectorAll('.lg.m:not([data-l])');
  for(var k=0;k<mono.length;k++){
   var el=mono[k];if(el.dataset.br)continue;el.dataset.br='1';
   var p=el.parentElement;if(!p)continue;
   var near=(el.nextElementSibling&&el.nextElementSibling.textContent)||(p.textContent||'').slice(0,60);
   var hit2=window.brandOf(near);
   if(!hit2||!BRANDS[hit2][0])continue;
   el.classList.remove('m');el.style.removeProperty('--mc');el.textContent='';
   el.setAttribute('data-l',BRANDS[hit2][0]);el.setAttribute('data-c',BRANDS[hit2][1]);
  }
 };
 window.fillLogos=function(root){
  root=root||document;
  if(root===document){window.brandify(document);window.decorateTools()}
  fill(root);
 };
})();

